public class EmuAmd64SyscallUseropLibraryTest : AbstractGhidraHeadlessIntegrationTest {

	/**
	 * A library with two 4-argument syscalls.
	 * <p>
	 * For x86:LE:64:default:gcc, the storage for the 4th argument varies by calling convention. For
	 * {@code __stdcall}, it's RCX. For syscall, it's R10. Both syscalls just return the 4th
	 * argument. Thus, it's possible to detect whether the emulator heeds conventions by binding
	 * each to a different convention, then invoking them with distinct values placed in RCX and R10
	 * and verifying that the correct value shows in RAX, the return register.
	 */
	protected static readonly class SyscallTestUseropLibrary : AnnotatedEmuSyscallUseropLibrary<byte[]> {

		public SyscallTestUseropLibrary(PcodeMachine<byte[]> machine, Program program) : base(machine, program)
    {
		}

		/* @PcodeUserop */
		public SleighPcodeUseropDefinition syscall(BuilderStage1 builder) {
			return builder.@params().body(_ => """
					RAX = emu_syscall(RAX);
					""").build();
		}

		/* @PcodeUserop */
		/* @EmuSyscall("syscall0") */
		public byte[] test_syscall0(byte[] arg0, byte[] arg1, byte[] arg2, byte[] arg3) {
			return arg3;
		}

		/* @PcodeUserop */
		/* @EmuSyscall("syscall1") */
		public byte[] test_syscall1(byte[] arg0, byte[] arg1, byte[] arg2, byte[] arg3) {
			return arg3;
		}
	}

	protected sealed class SyscallTestPcodeEmulator : PcodeEmulator {
		protected SyscallTestUseropLibrary syscalls;

		public SyscallTestPcodeEmulator() : base(program.getLanguage())
    {
		}

		/* @Override */
		protected PcodeUseropLibrary<byte[]> createUseropLibrary() {
			syscalls = new SyscallTestUseropLibrary(this, program);
			return syscalls;
		}
	}

	Program program;
	SleighLanguage language;
	Assembler asm;

	Register regRAX;
	AddressSpace space;
	Address start;
	int size;
	MemoryBlock block;
	PcodeArithmetic<byte[]> arithmetic;

	protected void placeSyscall(long number, string name, string convention)
    {
		AddressSpace spaceSyscall = program.getAddressFactory().getAddressSpace(SYSCALL_SPACE_NAME);
		FunctionManager functions = program.getFunctionManager();

		Address addr = spaceSyscall.getAddress(number);
		functions.createFunction(name, addr, new AddressSet(addr), SourceType.USER_DEFINED)
				.setCallingConvention(convention);
	}

	/* @Before */
	public void setUp()
    {
		program = createDefaultProgram("HelloSyscalls", "x86:LE:64:default", "gcc", this);
		language = (SleighLanguage) program.getLanguage();
		arithmetic = BytesPcodeArithmetic.forLanguage(language);

		regRAX = program.getRegister("RAX");
		space = program.getAddressFactory().getDefaultAddressSpace();
		start = space.getAddress(0x00400000);
		size = 0x1000;

		using (Transaction _ = program.openTransaction("Initialize"))
{
			block = program.getMemory()
					.createInitializedBlock(".text", start, size, (byte) 0, TaskMonitor.DUMMY,
						false);

			// Fulfill requirements for the syscall userop library:
			// 1) The "/pointer" data type exists, so it knows the machine word size
			program.getDataTypeManager()
					.resolve(PointerDataType.dataType, DataTypeConflictHandler.DEFAULT_HANDLER);
			// 2) Create the syscall space and add those we'll be using
			Address startOther = program.getAddressFactory()
					.getAddressSpace(SpaceNames.OTHER_SPACE_NAME)
					.getAddress(0);
			MemoryBlock blockSyscall = program.getMemory()
					.createUninitializedBlock(SYSCALL_SPACE_NAME, startOther, 0x10000, true);
			blockSyscall.setPermissions(true, false, true);

			placeSyscall(0, "syscall0", "__stdcall");
			placeSyscall(1, "syscall1", "syscall");

			asm = Assemblers.getAssembler(program);
		}
	}

	/* @After */
	public void tearDown() {
		if (program != null) {
			program.release(this);
		}
	}

	public SyscallTestPcodeEmulator prepareEmulator()
    {
		SyscallTestPcodeEmulator emu = new SyscallTestPcodeEmulator();
		byte[] buf = new byte[size];
		assertEquals(size, block.getBytes(start, buf));
		emu.getSharedState().setVar(space, start.getOffset(), size, true, buf);
		return emu;
	}

	public PcodeThread<byte[]> launchThread(PcodeEmulator emu, Address pc) {
		PcodeThread<byte[]> thread = emu.newThread();
		thread.overrideCounter(start);
		thread.overrideContextWithDefault();
		thread.reInitialize();
		return thread;
	}

	/* @Test */
	public void testSyscallWithStdcallConvention()
    {
		using (Transaction _ = program.openTransaction("Initialize"))
{
			asm.assemble(start,
				"MOV RAX,0",
				"MOV RCX,0xbeef", // Will be clobbered with RIP by SYSCALL
				"MOV R10,0xdead",
				"SYSCALL");
		}

		/**
		 * This test is a bit nonsensical, because the calling conventions will cause parameters to
		 * get pulled from registers that get clobbered by the SYSCALL, per the ISA description, not
		 * just convention. Still, I want to test that the emulator obeys the assigned calling
		 * convention.
		 */

		SyscallTestPcodeEmulator emu = prepareEmulator();
		PcodeThread<byte[]> thread = launchThread(emu, start);

		thread.stepInstruction(4);

		assertEquals("400017",
			thread.getState().inspectRegisterValue(regRAX).getUnsignedValue().toString(16));
	}

	/* @Test */
	public void testSyscallWithSyscallConvention()
    {
		using (Transaction _ = program.openTransaction("Initialize"))
{
			asm.assemble(start,
				"MOV RAX,1",
				"MOV RCX,0xdead", // Will be clobbered with RIP by SYSCALL
				"MOV R10,0xbeef",
				"SYSCALL");
		}

		SyscallTestPcodeEmulator emu = prepareEmulator();
		PcodeThread<byte[]> thread = launchThread(emu, start);

		thread.stepInstruction(4);

		assertEquals("beef",
			thread.getState().inspectRegisterValue(regRAX).getUnsignedValue().toString(16));
	}
}
